<?php
namespace Sabri\File26;

defined( 'ABSPATH' ) || exit;

/** Central-plan implementation layer. File 26 remains a derivative/search owner. */
final class Central_Plan {
	const META_SAVED_QUERIES = 'sabri_file26_saved_queries_v1';
	const OPTION_CONTENT_GAPS = 'sabri_file26_explicit_content_gaps_v1';
	const OPTION_MIGRATION = 'sabri_file26_central_plan_migration';
	const REST_NAMESPACE = 'sabri-search/v1';

	private $search; private $normalizer; private $security; private $ranking; private $doctor_ranking; private $health;
	public function __construct( Search $search, Normalizer $normalizer, Security $security, Ranking $ranking, Doctor_Ranking $doctor_ranking, Health $health ) { $this->search=$search; $this->normalizer=$normalizer; $this->security=$security; $this->ranking=$ranking; $this->doctor_ranking=$doctor_ranking; $this->health=$health; }

	public function boot() {
		if ( ! $this->migrate_settings() ) {
			DB::update_settings( array( 'activated'=>false, 'public_search_enabled'=>false, 'personalization_enabled'=>false ) );
			$this->security->audit( 'central_plan_migration_failed', array( 'object_type'=>'migration', 'object_key'=>self::OPTION_MIGRATION ) );
			add_action( 'admin_notices', static function(){ echo '<div class="notice notice-error"><p>' . esc_html__( 'File 26 central-plan settings migration could not be verified; search remains fail-closed.', 'sabri-file26' ) . '</p></div>'; } );
			return new \WP_Error( 'file26_central_plan_migration_failed', 'Central-plan settings migration could not be verified.' );
		}
		add_action( 'rest_api_init', array( $this, 'register_routes' ), 30 );
		add_filter( 'rest_post_dispatch', array( $this, 'augment_rest_response' ), 30, 3 );
		add_filter( 'rest_post_dispatch', array( $this, 'secure_route_response' ), 40, 3 );
		add_filter( 'wp_privacy_personal_data_exporters', array( $this, 'register_exporter' ) );
		add_filter( 'wp_privacy_personal_data_erasers', array( $this, 'register_eraser' ) );
		add_action( DB::CRON_RETENTION, array( $this, 'retention' ), 40 );
		return true;
	}

	public function register_routes() {
		$this->route('/advanced-search','GET','advanced_search','__return_true');
		$this->route('/saved-queries','GET','saved_queries','logged_in');
		$this->route('/saved-queries','POST','save_query','logged_in');
		$this->route('/saved-queries/(?P<query_id>[a-f0-9-]{36})','DELETE','delete_query','logged_in');
		$this->route('/ranking-constitution','GET','ranking_constitution_route','__return_true');
		$this->route('/content-gap','POST','submit_content_gap','logged_in');
		$this->route('/admin/editorial-radar','GET','editorial_radar','can_audit');
		$this->route('/admin/central-plan-status','GET','central_plan_status','can_audit');
	}
	private function route($path,$methods,$callback,$permission){register_rest_route(self::REST_NAMESPACE,$path,array('methods'=>$methods,'callback'=>array($this,$callback),'permission_callback'=>'__return_true'===$permission?'__return_true':array($this,$permission)));}
	public function logged_in(){if(!is_user_logged_in()){return new \WP_Error('file26_auth_required','Authentication is required.',array('status'=>401));}$audience=$this->security->audience();return !empty($audience['valid'])&&empty($audience['suspended'])?true:new \WP_Error('file26_membership_invalid','Current membership assertions are required.',array('status'=>403));}
	public function can_audit(){return $this->security->can_audit()?true:new \WP_Error('file26_forbidden','Search audit capability is required.',array('status'=>403));}

	/** CV-167 advanced search. */
	public function advanced_search( \WP_REST_Request $request ) {
