		$connector=sanitize_key((string)$request->get_param('connector'));if($connector){$filters['connector']=$connector;}$source=substr(sanitize_text_field((string)$request->get_param('source')),0,191);
		$extended=array('exact'=>$exact,'fields'=>$this->list_param($request->get_param('fields'),8),'excludes'=>$this->list_param($request->get_param('excludes'),12),'verification'=>sanitize_key((string)$request->get_param('verification')),'format'=>sanitize_key((string)$request->get_param('format')),'access'=>sanitize_key((string)$request->get_param('access')),'source'=>$source);
		$limit=max(1,min(30,(int)($request->get_param('limit')?:20)));$context_hash=hash('sha256',wp_json_encode(array('q'=>$q,'locale'=>$request->get_param('locale'),'filters'=>$filters,'extended'=>$extended,'limit'=>$limit)));$offset=0;
		if($request->get_param('cursor')){$verified=$this->security->verify_cursor((string)$request->get_param('cursor'));if(!$verified||empty($verified['h'])||!hash_equals($context_hash,(string)$verified['h'])||!isset($verified['ao'])){return new \WP_Error('file26_invalid_advanced_cursor','The advanced-search cursor is invalid or expired.',array('status'=>400));}$offset=max(0,min(10000,(int)$verified['ao']));}
		$default_pages=max(2,min(20,(int)apply_filters('sabri_file26_advanced_scan_pages',10)));$required_pages=(int)ceil(($offset+$limit)/30)+2;$max_pages=min(20,max($default_pages,$required_pages));$base_cursor='';$collected=array();$seen=array();$pages=0;$partial=false;$partial_domains=array();$base_has_more=false;
		do{$base=$this->search->run(array('q'=>$q,'locale'=>$request->get_param('locale'),'cursor'=>$base_cursor,'limit'=>30,'filters'=>$filters));if(is_wp_error($base)){return $base;}$pages++;$partial=$partial||!empty($base['partial']);$partial_domains=array_merge($partial_domains,isset($base['partial_domains'])?(array)$base['partial_domains']:array());$rows=(array)$base['results'];$meta=$this->advanced_metadata(wp_list_pluck($rows,'key'));foreach($rows as $item){$key=isset($item['key'])?(string)$item['key']:'';if(''===$key||isset($seen[$key])||!$this->matches_extended($item,$q,$extended,isset($meta[$key])?$meta[$key]:array())){continue;}$seen[$key]=true;$collected[]=$item;}$base_cursor=!empty($base['next_cursor'])?(string)$base['next_cursor']:'';$base_has_more=(bool)$base_cursor;}while($base_cursor&&$pages<$max_pages);
		$total_collected=count($collected);$page_results=array_slice($collected,$offset,$limit);$has_more_collected=$total_collected>($offset+$limit);$bounded_more=$base_has_more&&$pages>=$max_pages;$continuation_limited=$bounded_more&&!$page_results&&$offset>=$total_collected;$next_cursor=null;if($has_more_collected||($bounded_more&&!$continuation_limited&&$page_results)){$next_offset=$offset+count($page_results);if($next_offset>$offset){$next_cursor=$this->security->sign_cursor(array('ao'=>$next_offset,'h'=>$context_hash));}}
		$response=array('contract_version'=>SABRI_FILE26_CONTRACT_VERSION,'query'=>$q,'query_normalized'=>$this->normalizer->normalize($q),'policy_version'=>$this->ranking->policy_version(),'results'=>$page_results,'next_cursor'=>$next_cursor,'partial'=>$partial||$bounded_more,'partial_domains'=>array_values($this->unique_arrays($partial_domains)),'advanced_search'=>array('exact_phrase'=>$exact,'fields'=>$extended['fields'],'excludes'=>$extended['excludes'],'verification'=>$extended['verification'],'format'=>$extended['format'],'access'=>$extended['access'],'source'=>$source,'connector'=>$connector,'bounded_source_pages_scanned'=>$pages,'bounded_eligible_matches'=>$total_collected,'continuation_limited'=>$continuation_limited));
		return rest_ensure_response($this->augment_search_result($response,array('q'=>$q,'locale'=>$request->get_param('locale'))));
	}

	private function advanced_metadata(array $keys){global $wpdb;$keys=array_values(array_filter(array_unique($keys),static function($key){return is_string($key)&&preg_match('/^[a-f0-9]{64}$/',$key);}));if(!$keys){return array();}$placeholders=implode(',',array_fill(0,count($keys),'%s'));$table=DB::table('documents');$rows=$wpdb->get_results($wpdb->prepare("SELECT canonical_key,connector_slug,visibility,state,locale,author_key,topic_ids,normalized_title,normalized_body,payload FROM $table WHERE canonical_key IN ($placeholders)",$keys),ARRAY_A);if(null===$rows){return array();}$map=array();foreach((array)$rows as $row){$row['payload_array']=json_decode($row['payload'],true);$row['payload_array']=is_array($row['payload_array'])?$row['payload_array']:array();$row['topics_array']=json_decode($row['topic_ids'],true);$row['topics_array']=is_array($row['topics_array'])?$row['topics_array']:array();$map[$row['canonical_key']]=$row;}return $map;}
	private function matches_extended(array $item,$query,array $extended,array $meta){$payload=isset($meta['payload_array'])&&is_array($meta['payload_array'])?$meta['payload_array']:(isset($item['payload'])&&is_array($item['payload'])?$item['payload']:array());$topics=isset($meta['topics_array'])?(array)$meta['topics_array']:(isset($item['topics'])?(array)$item['topics']:array());$title=isset($meta['normalized_title'])?$meta['normalized_title']:(isset($item['title'])?$item['title']:'');$body=isset($meta['normalized_body'])?$meta['normalized_body']:(isset($item['excerpt'])?$item['excerpt']:'');$author=isset($meta['author_key'])?$meta['author_key']:(isset($item['author_key'])?$item['author_key']:'');$haystack=$this->normalizer->normalize(implode(' ',array($title,$body,$author,implode(' ',$topics))));foreach($extended['excludes'] as $excluded){$excluded=$this->normalizer->normalize($excluded);if($excluded&&false!==$this->strpos($haystack,$excluded)){return false;}}if($extended['fields']&&$query){$field_text=array();foreach($extended['fields'] as $field){if('title'===$field){$field_text[]=$title;}elseif(in_array($field,array('body','excerpt','summary'),true)){$field_text[]=$body;}elseif('author'===$field){$field_text[]=$author;}elseif(in_array($field,array('topic','topics'),true)){$field_text[]=implode(' ',$topics);}}$field_haystack=$this->normalizer->normalize(implode(' ',$field_text));if($extended['exact']&&false===$this->strpos($field_haystack,$this->normalizer->normalize($extended['exact']))){return false;}$matched=false;foreach($this->normalizer->tokens($query) as $token){if(false!==$this->strpos($field_haystack,$token)){$matched=true;break;}}if(!$matched){return false;}}
