	public function saved_queries(){$user_id=get_current_user_id();$queries=array();foreach($this->load_saved_queries($user_id,true) as $record){$queries[]=$this->public_saved_record($record,$user_id);}return rest_ensure_response(array('contract_version'=>SABRI_FILE26_CONTRACT_VERSION,'queries'=>$queries,'used_for_personalization'=>false));}
	public function save_query(\WP_REST_Request $request){
