	}
	private function sanitize_envelope(array $envelope){return array('ciphertext'=>substr(sanitize_text_field($envelope['ciphertext']),0,12000),'key_id'=>substr(sanitize_key($envelope['key_id']),0,120),'version'=>substr(sanitize_text_field(isset($envelope['version'])?$envelope['version']:'1'),0,30),'algorithm'=>substr(sanitize_text_field(isset($envelope['algorithm'])?$envelope['algorithm']:'provider-managed'),0,80));}
