	public function delete_query(\WP_REST_Request $request){$user_id=get_current_user_id();$id=strtolower((string)$request['query_id']);$lock=$this->acquire_saved_query_lock($user_id);if(is_wp_error($lock)){return $lock;}try{$stored=get_user_meta($user_id,self::META_SAVED_QUERIES,true);$stored=is_array($stored)?$stored:array();$queries=$this->prune_saved_queries($stored);if(!isset($queries[$id])){return new \WP_Error('file26_saved_query_not_found','Saved query not found.',array('status'=>404));}unset($queries[$id]);$written=update_user_meta($user_id,self::META_SAVED_QUERIES,$queries);if(false===$written&&get_user_meta($user_id,self::META_SAVED_QUERIES,true)!==$queries){return new \WP_Error('file26_saved_query_delete_failed','The saved query could not be deleted.',array('status'=>500));}$this->security->audit('saved_query_deleted',array('object_type'=>'saved_query','object_key'=>$id));return rest_ensure_response(array('deleted'=>true,'id'=>$id));}finally{$this->release_named_lock($lock);}}

	public function ranking_constitution_route(){return rest_ensure_response($this->ranking_constitution());}
	public function ranking_constitution(){$search=$this->ranking->policy('search','public');$doctor=$this->doctor_ranking->policy();return array('contract_version'=>SABRI_FILE26_CONTRACT_VERSION,'organic_search'=>array('policy_version'=>$search['version'],'signals'=>$search['weights'],'diversity_limits'=>$search['limits']),'doctor_ranking'=>array('policy_version'=>$doctor['version'],'signals'=>$doctor['weights'],'tiers'=>array('top_10','top_100','top_1000','all_verified'),'recompute'=>'monthly and after an upheld corrective appeal','safe_fallback'=>!empty($doctor['safe_fallback'])),'constitutional_priorities'=>array('relevance','educational_value','source_authority','safety','provenance','freshness','diversity','user_control'),'prohibited_signals'=>array('donation','payment','paid_promotion','advertising','follower_count','founder_favoritism','private_messages','clinical_records','identity_evidence'),'paid_or_sponsored_organic_results'=>false,'single_free_tier_rank_parity'=>true,'why_this_result_required'=>true,'user_controls'=>array('hide_item','hide_author','hide_topic','not_interested','undo','reset','opt_out'));}

	public function submit_content_gap(\WP_REST_Request $request){$user_id=get_current_user_id();if(!$this->security->rate_limit('content-gap|u:'.$user_id,8,HOUR_IN_SECONDS)){return new \WP_Error('file26_rate_limited','Too many content-gap submissions.',array('status'=>429));}$params=(array)$request->get_json_params();if(true!==$this->strict_bool(isset($params['consent'])?$params['consent']:null)){return new \WP_Error('file26_gap_consent_required','Explicit boolean submission consent is required.',array('status'=>400));}$query=$this->security->sanitize_query(isset($params['q'])?$params['q']:'');if(''===$query||$this->security->contains_sensitive_query($query)){return new \WP_Error('file26_gap_sensitive_or_empty','Empty or sensitive queries are not retained as editorial content gaps.',array('status'=>400));}$normalized=substr($this->normalizer->normalize($query),0,180);$key=hash_hmac('sha256',$normalized,wp_salt('auth'));$lock=$this->acquire_content_gap_lock();if(is_wp_error($lock)){return $lock;}try{$registry=get_option(self::OPTION_CONTENT_GAPS,array());$registry=is_array($registry)?$registry:array();$now=DB::now();$current=isset($registry[$key])&&is_array($registry[$key])?$registry[$key]:array();$retention_days=$this->setting_days('explicit_gap_retention_days',90,7,365);$registry[$key]=array('key'=>$key,'query'=>$normalized,'locale'=>substr(sanitize_text_field(isset($params['locale'])?$params['locale']:determine_locale()),0,20),'count'=>isset($current['count'])?min(1000000,(int)$current['count']+1):1,'first_seen'=>isset($current['first_seen'])?$current['first_seen']:$now,'last_seen'=>$now,'expires_at'=>gmdate('Y-m-d H:i:s',time()+($retention_days*DAY_IN_SECONDS)),'status'=>'open','identity_stored'=>false,'source'=>'explicit_user_submission');if(count($registry)>200){uasort($registry,static function($a,$b){return strcmp($a['last_seen'],$b['last_seen']);});$registry=array_slice($registry,-200,null,true);}$saved=update_option(self::OPTION_CONTENT_GAPS,$registry,false);if(!$saved&&get_option(self::OPTION_CONTENT_GAPS,array())!==$registry){return new \WP_Error('file26_content_gap_write_failed','The content-gap registry could not be updated.',array('status'=>500));}$this->record_aggregate_metric('explicit_content_gap',isset($params['locale'])?$params['locale']:determine_locale(),1,0);return rest_ensure_response(array('accepted'=>true,'identity_stored'=>false,'retention_days'=>$retention_days));}finally{$this->release_named_lock($lock);}}

	public function editorial_radar(\WP_REST_Request $request){global $wpdb;$days=max(1,min(90,(int)($request->get_param('days')?:30)));$from=gmdate('Y-m-d',time()-(($days-1)*DAY_IN_SECONDS));$table=DB::table('metrics');$rows=$wpdb->get_results($wpdb->prepare("SELECT metric_key,locale,SUM(count_value) AS total_count,SUM(sum_value) AS total_value,MAX(metric_date) AS latest_date FROM $table WHERE metric_date >= %s GROUP BY metric_key,locale ORDER BY total_count DESC LIMIT 250",$from),ARRAY_A);if(null===$rows){return new \WP_Error('file26_editorial_radar_read_failed','Editorial radar metrics could not be read.',array('status'=>500));}$gaps=get_option(self::OPTION_CONTENT_GAPS,array());$gaps=is_array($gaps)?array_values($gaps):array();$now=time();$gaps=array_values(array_filter($gaps,function($gap)use($now){return is_array($gap)&&!empty($gap['expires_at'])&&$this->parse_timestamp($gap['expires_at'])>=$now;}));usort($gaps,static function($a,$b){return (int)$a['count']===(int)$b['count']?strcmp($b['last_seen'],$a['last_seen']):((int)$b['count']<=>(int)$a['count']);});return rest_ensure_response(array('contract_version'=>SABRI_FILE26_CONTRACT_VERSION,'window_days'=>$days,'aggregate_metrics'=>$rows,'rising_explicit_content_gaps'=>array_slice($gaps,0,50),'private_user_identity_included'=>false,'raw_sensitive_query_history_included'=>false,'trend_truth_owner'=>'File 15; this File 26 surface is editorial/search telemetry only','health'=>$this->health->snapshot()));}

	public function central_plan_status(){return rest_ensure_response(array('version'=>SABRI_FILE26_VERSION,'contract_version'=>SABRI_FILE26_CONTRACT_VERSION,'governing_addendum'=>'6-Aug-2026 three-central-plan continuous-value requirements','coded_requirements'=>array('CV-164','CV-165','CV-166','CV-167','CV-168','CV-169','CV-172','CV-173','CV-174','CV-175','F26-CEN-01','F26-CEN-02'),'consumer_only_boundaries'=>array('CV-170'=>'File 06/15 canonical knowledge/research owner','CV-171'=>'File 15 trend owner'),'brand_primary_fallback'=>'#087A4E','single_free_tier'=>true,'live_status_claimed'=>false));}
	public function augment_rest_response($response,$server,$request){if(!$request instanceof \WP_REST_Request||'/sabri-search/v1/search'!==$request->get_route()||is_wp_error($response)){return $response;}$response=rest_ensure_response($response);$data=$response->get_data();if(!is_array($data)){return $response;}$response->set_data($this->augment_search_result($data,array('q'=>$request->get_param('q'),'locale'=>$request->get_param('locale'))));return $response;}
