	public function safety_for_query($query,$locale='und'){$normalized=$this->normalizer->normalize($query);$risk='general';$reason='general_discovery';$patterns=array('emergency'=>array('suicide','kill myself','self harm','cut myself','cannot breathe',"can't breathe",'severe bleeding','unconscious','chest pain','خودکشی','جان دینا','خود کو نقصان','اپنے آپ کو کاٹ','سانس نہیں','سانس بند','شدید خون','سینے میں شدید درد','بے ہوش'),'safety_support'=>array('domestic violence','abuse victim','violence at home','sexual abuse','harassment victim','گھریلو تشدد','جنسی زیادتی','ہراسانی','تشدد کا شکار'),'harmful'=>array('how to poison','how to kill','make explosive','زہر دے','قتل کیسے','بم بن'),'clinical'=>array('dose','dosage','prescription','potency','stop medicine','خوراک','پوٹینسی','نسخہ','دوا بند'));foreach(array('emergency','safety_support','harmful','clinical') as $class){foreach($patterns[$class] as $pattern){if($pattern&&false!==$this->strpos($normalized,$this->normalizer->normalize($pattern))){$risk=$class;$reason='matched_'.$class.'_safety_policy';break 2;}}}$resource=apply_filters('sabri_file26_verified_emergency_resource',null,$locale,$risk);$resource=$this->verified_current_resource($resource);$guidance=null;if('emergency'===$risk){$guidance='If there may be immediate danger or a medical emergency, do not wait for platform search or an appointment. Seek qualified local emergency care now.';}elseif('safety_support'===$risk){$guidance='If you may be unsafe because of violence, abuse or harassment, seek trusted qualified local support. If there is immediate danger, use local emergency services.';}elseif('harmful'===$risk){$guidance='Search results are constrained to safety-oriented, lawful information and cannot provide instructions intended to harm a person.';}elseif('clinical'===$risk){$guidance='Search is educational and does not replace individualized diagnosis, prescription, dosage or emergency care.';}return array('risk_class'=>$risk,'reason_code'=>$reason,'educatio