	private function verified_current_resource($resource){if(!is_array($resource)||empty($resource['verified'])||empty($resource['label'])||empty($resource['verified_at'])){return null;}$verified_at=$this->parse_timestamp($resource['verified_at']);$expires_at=!empty($resource['expires_at'])?$this->parse_timestamp($resource['expires_at']):0;$max_age=max(DAY_IN_SECONDS,min(90*DAY_IN_SECONDS,(int)apply_filters('sabri_file26_emergency_resource_max_age',30*DAY_IN_SECONDS)));if(!$verified_at||$verified_at<time()-$max_age||($expires_at&&$expires_at<time())){return null;}$out=array('label'=>substr(sanitize_text_field($resource['label']),0,160),'verified'=>true,'verified_at'=>gmdate('c',$verified_at),'expires_at'=>$expires_at?gmdate('c',$expires_at):null);if(!empty($resource['url'])){$url=$this->security->safe_resource_url($resource['url'],'emergency_resource');if($url){$out['url']=$url;}}if(!empty($resource['phone'])){$out['phone']=substr(preg_replace('/[^0-9+()\-\s]/','',(string)$resource['phone']),0,40);}return $out;}
	private function zero_result_recovery($query,$locale,array $safety){global $wpdb;$candidates=array();foreach($this->normalizer->retrieval_terms($query) as $term){$term=sanitize_text_field($term);if($term&&$this->normalizer->normalize($term)!==$this->normalizer->normalize($query)){$candidates[]=$term;}}$candidates=array_slice(array_values(array_unique($candidates)),0,6);$related=array();$normalized=$this->normalizer->normalize($query);if($normalized&&strlen($normalized)>=2){$terms=DB::table('terms');$aliases=DB::table('term_aliases');$like='%'.$wpdb->esc_like(substr($normalized,0,80)).'%';$related=$wpdb->get_results($wpdb->prepare("SELECT DISTINCT t.term_uuid,t.preferred_label,t.language FROM $terms t LEFT JOIN $aliases a ON a.term_uuid=t.term_uuid AND a.status='active' WHERE t.status='active' AND (t.preferred_label LIKE %s OR a.alias_normalized LIKE %s) ORDER BY t.preferred_label LIMIT 6",$like,$like),ARRAY_A);$related=is_array($related)?$related:array();}$can_submit=is_user_logged_in()&&'general'===$safety['risk_class']&&!$this->security->contains_sensitive_query($query);$help=apply_filters('sabri_file26_zero_result_help_destination',null,$locale,$query);$help_url=is_array($help)&&!empty($help['url'])?$this->security->safe_resource_url($help['url'],'zero_result_help'):'';return array('spelling_or_transliteration_candidates'=>$candidates,'related_topics'=>$related,'actions'=>array('adjust_filters'=>true,'browse_topics'=>true,'submit_content_gap'=>$can_submit,'ask_expert_destination_owner'=>'File 17/approved support owner','ask_expert_url'=>$help_url?$help_url:null),'fabricated_result'=>false,'query_retained_for_gap_without_explicit_consent'=>false);}

	private function augment_freshness(array $response){global $wpdb;$results=isset($response['results'])&&is_array($response['results'])?$response['results']:array();$summary=array('known'=>0,'within_slo'=>0,'stale'=>0,'unknown'=>0);if(!$results){$response['index_freshness']=$summary;return $response;}$keys=array_values(array_filter(wp_list_pluck($results,'key'),static function($key){return is_string($key)&&preg_match('/^[a-f0-9]{64}$/',$key);}));$map=array();if($keys){$placeholders=implode(',',array_fill(0,count($keys),'%s'));$documents=DB::table('documents');$rows=$wpdb->get_results($wpdb->prepare("SELECT canonical_key,connector_slug,entity_type,locale,state,visibility,freshness_at,indexed_at,payload FROM $documents WHERE canonical_key IN ($placeholders)",$keys),ARRAY_A);foreach((array)$rows as $row){$map[$row['canonical_key']]=$row;}}
