	private function parse_timestamp($value){if(!is_string($value)||''===trim($value)){return 0;}$value=trim($value);$has_zone=(bool)preg_match('/(?:Z|[+\-]\d{2}:?\d{2})$/i',$value);$ts=strtotime($has_zone?$value:$value.' UTC');return $ts?(int)$ts:0;}
