	private function load_saved_queries($user_id,$persist_cleanup=true){$user_id=(int)$user_id;$stored=get_user_meta($user_id,self::META_SAVED_QUERIES,true);$stored=is_array($stored)?$stored:array();$value=$this->prune_saved_queries($stored);if($persist_cleanup&&$value!==$stored){$lock=$this->acquire_saved_query_lock($user_id);if(!is_wp_error($lock)){try{$current=get_user_meta($user_id,self::META_SAVED_QUERIES,true);$current=is_array($current)?$current:array();$pruned=$this->prune_saved_queries($current);if($pruned!==$current){$saved=update_user_meta($user_id,self::META_SAVED_QUERIES,$pruned);if(false===$saved&&get_user_meta($user_id,self::META_SAVED_QUERIES,true)!==$pruned){$this->security->audit('saved_query_retention_write_failed',array('object_type'=>'retention','object_key'=>(string)$user_id));}}$value=$pruned;}finally{$this->release_named_lock($lock);}}}return $value;}
