	private function strict_bool($value){if(is_bool($value)){return $value;}if(is_int($value)||is_float($value)){if(1===(int)$value){return true;}if(0===(int)$value){return false;}return null;}if(is_string($value)){$value=strtolower(trim($value));if(in_array($value,array('1','true','yes','on'),true)){return true;}if(in_array($value,array('0','false','no','off'),true)){return false;}}return null;}
	private function sanitize_saved_filters($filters){$filters=is_array($filters)?$filters:array();$clean=array();foreach(array('entity_type','country','location','availability','connector','domain','topic','sort','language') as $key){if(!empty($filters[$key])){$clean[$key]=substr(sanitize_text_field($filters[$key]),0,191);}}if(!empty($filters['author'])){$clean['author']=substr(sanitize_text_field($filters['author']),0,191);}foreach(array('date_from','date_to') as $key){if(!empty($filters[$key])&&preg_match('/^(\d{4})-(\d{2})-(\d{2})$/',$filters[$key],$m)&&checkdate((int)$m[2],(int)$m[3],(int)$m[1])){$clean[$key]=$filters[$key];}}return $clean;}
