	private function unique_arrays(array $items){$out=array();$seen=array();foreach($items as $item){$key=hash('sha256',wp_json_encode($item));if(!isset($seen[$key])){$seen[$key]=true;$out[]=$item;}}return $out;}
	private function strpos($haystack,$needle){return function_exists('mb_strpos')?mb_strpos((string)$haystack,(string)$needle,0,'UTF-8'):strpos((string)$haystack,(string)$needle);}
	private function setting_days($key,$default,$min,$max){return max((int)$min,min((int)$max,(int)DB::setting($key,$default)));}

	private function migrate_settings(){$current=get_option(DB::OPTION_SETTINGS,array());$current=is_array($current)?$current:array();$changed=false;if(empty($current['primary_color'])||in_array(strtolower((string)$current['primary_color']),array('#138a36','#ff8a1f'),true)){$current['primary_color']='#087A4E';$changed=true;}$defaults=array('single_free_tier'=>true,'paid_organic_results_enabled'=>false,'donation_ranking_signal_enabled'=>false,'saved_query_retention_days'=>365,'sensitive_saved_query_retention_days'=>90,'explicit_gap_retention_days'=>90);foreach($defaults as $key=>$value){if(!array_key_exists($key,$current)){$current[$key]=$value;$changed=true;}}if($changed){$saved=update_option(DB::OPTION_SETTINGS,$current,false);if(!$saved&&get_option(DB::OPTION_SETTINGS,array())!==$current){return false;}}$marker=update_option(self::OPTION_MIGRATION,'1.2.0',false);return $marker||'1.2.0'===get_option(self::OPTION_MIGRATION);}
	public function retention(){$lock=$this->acquire_content_gap_lock();if(is_wp_error($lock)){$this->security->audit('content_gap_retention_lock_failed',array('object_type'=>'retention'));return $lock;}try{$registry=get_option(self::OPTION_CONTENT_GAPS,array());$registry=is_array($registry)?$registry:array();$now=time();$changed=false;foreach($registry as $key=>$record){if(!is_array($record)||empty($record['expires_at'])||$this->parse_timestamp($record['expires_at'])<$now){unset($registry[$key]);$changed=true;}}if($changed){$saved=update_option(self::OPTION_CONTENT_GAPS,$registry,false);if(!$saved&&get_option(self::OPTION_CONTENT_GAPS,array())!==$registry){$this->security->audit('content_gap_retention_write_failed',array('object_type'=>'retention'));return new \WP_Error('file26_content_gap_retention_failed','Content-gap retention could not be persisted safely.');}}return true;}finally{$this->release_named_lock($lock);}}

	public function register_exporter($exporters){$exporters['sabri-file26-saved-queries']=array('exporter_friendly_name'=>__('File 26 saved search queries','sabri-file26'),'callback'=>array($this,'privacy_export'));return $exporters;}
	public function register_eraser($erasers){$erasers['sabri-file26-saved-queries']=array('eraser_friendly_name'=>__('File 26 saved search queries','sabri-file26'),'callback'=>array($this,'privacy_erase'));return $erasers;}
	public function privacy_export($email_address,$page=1){$user=get_user_by('email',$email_address);if(!$user||(int)$page>1){return array('data'=>array(),'done'=>true);}$data=array();foreach($this->load_saved_queries($user->ID,true) as $record){$public=$this->public_saved_record($record,$user->ID,false);$data[]=array('group_id'=>'sabri-file26-saved-queries','group_label'=>__('Saved search queries','sabri-file26'),'item_id'=>'saved-query-'.$record['id'],'data'=>array(array('name'=>__('Name','sabri-file26'),'value'=>$public['name']),array('name'=>__('Query','sabri-file26'),'value'=>!empty($public['q'])?$public['q']:'[protected sensitive query]'),array('name'=>__('Filters','sabri-file26'),'value'=>wp_json_encode($public['filters'])),array('name'=>__('Updated','sabri-file26'),'value'=>$public['updated_at']))); }return array('data'=>$data,'done'=>true);}
	public function privacy_erase($email_address,$page=1){$user=get_user_by('email',$email_address);if(!$user||(int)$page>1){return array('items_removed'=>false,'items_retained'=>false,'messages'=>array(),'done'=>true);}$lock=$this->acquire_saved_query_lock($user->ID);if(is_wp_error($lock)){return array('items_removed'=>false,'items_retained'=>true,'messages'=>array(__('Saved search queries are being updated; erasure did not start.','sabri-file26')),'done'=>false);}try{$had=(bool)get_user_meta($user->ID,self::META_SAVED_QUERIES,true);$deleted=delete_user_meta($user->ID,self::META_SAVED_QUERIES);if($had&&!$deleted&&get_user_meta($user->ID,self::META_SAVED_QUERIES,true)){return array('items_removed'=>false,'items_retained'=>true,'messages'=>array(__('Saved search queries could not be erased.','sabri-file26')),'done'=>false);}return array('items_removed'=>$had,'items_retained'=>false,'messages'=>array(),'done'=>true);}finally{$this->release_named_lock($lock);}}
